const normalizeString = (str) => {
    if (!str)
        return '';
    return String(str)
        .replace(/[أإآ]/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي')
        .replace(/[٠-٩]/g, d => '0123456789'['٠١٢٣٤٥٦٧٨٩'.indexOf(d)])
        .toLowerCase()
        .trim();
};
// --- Search Helper Functions ---
const searchIncludes = (dataStr, searchStr) => {
    if (!searchStr)
        return true;
    return normalizeString(dataStr).includes(normalizeString(searchStr));
};
const searchAllTerms = (dataStr, searchStr) => {
    if (!searchStr)
        return true;
    const normData = normalizeString(dataStr);
    const terms = normalizeString(searchStr).split(' ').filter(t => t.trim() !== '');
    return terms.every(term => normData.includes(term));
};
const searchAnyTerm = (dataStr, searchStr) => {
    if (!searchStr)
        return true;
    const normData = normalizeString(dataStr);
    const terms = normalizeString(searchStr).split(' ').filter(t => t.trim() !== '');
    return terms.some(term => normData.includes(term));
};
