const handleTransformerRegistrationSubmit = async (event) => {
    event.preventDefault();
    const form = event.target;
    if (!validateForm(form)) {
        showToast('يرجى ملء جميع الحقول المطلوبة.', 'error');
        return;
    }
    const idInput = document.getElementById('transformer-id');
    if (idInput.value && !hasButtonPermission('edit_button')) {
        showToast('ليس لديك صلاحية تعديل المحولات.', 'error');
        return;
    }
    const id = idInput.value ? parseInt(idInput.value, 10) : Date.now();
    const newTransformer = {
        id: id,
        councilName: document.getElementById('councilName').value,
        transformerName: document.getElementById('transformerName').value,
        transformerAddress: document.getElementById('transformerAddress').value,
        transformerType: document.getElementById('transformerType').value,
        transformerCapacityKVA: parseInt(document.getElementById('transformerCapacityKVA').value, 10),
        smartMeterChassis: document.getElementById('smartMeterChassis').value,
        simCardNumber: document.getElementById('simCardNumber').value,
        currentTransformerCapacity: document.getElementById('currentTransformerCapacity').value,
    };
    if (idInput.value) { // Editing
        const index = state.transformers.findIndex(t => t.id === id);
        if (index !== -1)
            state.transformers[index] = newTransformer;
        logActivity('تعديل محول', `تم تعديل بيانات المحول: ${newTransformer.transformerName}`);
    }
    else { // Adding
        state.transformers.push(newTransformer);
        logActivity('إضافة محول', `تم إضافة محول جديد: ${newTransformer.transformerName}`);
        console.log('State.transformers after push (before save):', state.transformers); // Added log
    }
    if (await saveState()) {
        showToast('تم حفظ بيانات المحول بنجاح.');
        form.reset(); // تفريغ الحقول
        clearFormErrors(form); // مسح رسائل الأخطاء إن وجدت
        document.getElementById('transformer-id').value = ''; // التأكد من مسح ID المحول
        renderTransformerListSection(); // تحديث قائمة المحولات في الخلفية
    }
};
