// --- قراءة الكارت الذكي عبر قارئ الكروت (OMNIKEY) ---
const handleReadSmartCard = async () => {
    const readBtn = document.getElementById('statement-read-card-btn');
    const originalBtnHtml = readBtn ? readBtn.innerHTML : '';
    if (readBtn) {
        readBtn.disabled = true;
        readBtn.innerHTML = `
                <span style="display:inline-block; width:16px; height:16px; border:2px solid #fff; border-top-color:transparent; border-radius:50%; animation:spin 1s linear infinite; vertical-align:middle; margin-left:6px;"></span>
                <span>جاري التعامل مع الكارت...</span>
            `;
    }
    try {
        showToast('جاري فحص القارئ والتعامل مع الكارت...');
        let result = null;
        if (window.readSmartCard) {
            result = await window.readSmartCard();
        }
        else {
            try {
                const res = await fetch('http://127.0.0.1:5002/api/read-smart-card');
                result = await res.json();
            }
            catch (bridgeErr) {
                showToast('تعذر الاتصال بخدمة قراءة الكروت المحلية. تأكد من تشغيل الخدمة على جهازك.', 'error');
                return;
            }
        }
        if (!result) {
            showToast('لم يتم استلام أي استجابة من خدمة قراءة الكروت.', 'error');
            return;
        }
        if (result.status === 'no_reader') {
            showToast(result.message || 'لم يتم العثور على قارئ كروت ذكية متصل بالجهاز. يرجى توصيل قارئ OMNIKEY.', 'error');
            return;
        }
        if (result.status === 'no_card') {
            showToast(result.message || 'قارئ الكروت متصل ولكن لم يتم إدخال كارت. يرجى إدخال الكارت في القارئ والمحاولة مجدداً.', 'error');
            return;
        }
        const card = result.card || result.cardData;
        if (result.success && card) {
            const meterChassis = card.meterChassisNumber || '';
            const subscriptionCode = card.subscriptionCode || '';
            const vendorName = card.vendorName || card.meterSupplyCompany || 'غير محدد';
            const cardType = card.cardType || 'كارت ذكي مسبق الدفع';
            const readerName = card.readerName || 'HID Global OMNIKEY';
            const readAtText = card.readTime || (card.readAt ? new Date(card.readAt).toLocaleString('ar-EG') : new Date().toLocaleString('ar-EG'));
            // Fill search inputs in statement form
            const chassisInput = document.getElementById('statement-search-meterChassisNumber');
            const codeInput = document.getElementById('statement-search-subscriptionCode');
            if (chassisInput && meterChassis) {
                chassisInput.value = meterChassis;
            }
            if (codeInput && subscriptionCode) {
                codeInput.value = subscriptionCode;
            }
            // Populate and show the modal dialog
            const dialog = document.getElementById('smart-card-details-dialog');
            const chassisEl = document.getElementById('sc-meter-chassis');
            const codeEl = document.getElementById('sc-subscription-code');
            const vendorEl = document.getElementById('sc-vendor-name');
            const cardTypeEl = document.getElementById('sc-card-type');
            const readerEl = document.getElementById('sc-reader-name');
            const timeEl = document.getElementById('sc-read-time');
            const matchAlertEl = document.getElementById('sc-match-alert');
            if (chassisEl)
                chassisEl.textContent = meterChassis || '-';
            if (codeEl)
                codeEl.textContent = subscriptionCode || '-';
            if (vendorEl)
                vendorEl.textContent = vendorName;
            if (cardTypeEl)
                cardTypeEl.textContent = cardType;
            if (readerEl)
                readerEl.textContent = readerName;
            if (timeEl)
                timeEl.textContent = readAtText;
            // Check matches in database
            const matches = state.meters.filter(m => {
                const matchChassis = meterChassis && ((m.meterChassisNumber && String(m.meterChassisNumber).trim() === meterChassis) ||
                    (m.newMeterChassisNumber && String(m.newMeterChassisNumber).trim() === meterChassis) ||
                    (m.newMeterChassisNumberForReplacement && String(m.newMeterChassisNumberForReplacement).trim() === meterChassis) ||
                    (m.oldMeterChassisNumber && String(m.oldMeterChassisNumber).trim() === meterChassis));
                const matchCode = subscriptionCode && (m.subscriptionCode && String(m.subscriptionCode).trim() === subscriptionCode);
                return matchChassis || matchCode;
            });
            if (matchAlertEl) {
                if (matches.length > 0) {
                    matchAlertEl.style.display = 'block';
                    matchAlertEl.style.backgroundColor = '#dcfce7';
                    matchAlertEl.style.color = '#166534';
                    matchAlertEl.style.border = '1px solid #86efac';
                    matchAlertEl.innerHTML = `<strong>تم العثور على (${matches.length}) سجل في قاعدة بيانات المنظومة!</strong> المشترك: ${matches[0].subscriberName || 'غير مسجل'}.`;
                }
                else {
                    matchAlertEl.style.display = 'block';
                    matchAlertEl.style.backgroundColor = '#fef3c7';
                    matchAlertEl.style.color = '#92400e';
                    matchAlertEl.style.border = '1px solid #fde68a';
                    matchAlertEl.innerHTML = `<strong>تمت قراءة بيانات الكارت بنجاح:</strong> لكن لم يتم العثور على سجلات مسجلة مسبقاً بهذا الشاسية في المنظومة.`;
                }
            }
            if (dialog) {
                dialog.hidden = false;
            }
            showToast(`تمت قراءة الكارت بنجاح! رقم الشاسية: ${meterChassis}`, 'success');
            // If matches found, auto-trigger search to display them immediately under the form
            if (matches.length > 0) {
                handleSubscriberStatementSearch();
            }
        }
        else {
            showToast(result.message || 'فشلت قراءة بيانات الكارت.', 'error');
        }
    }
    catch (error) {
        console.error('Error in handleReadSmartCard:', error);
        showToast(`حدث خطأ أثناء قراءة الكارت: ${error.message || error}`, 'error');
    }
    finally {
        if (readBtn) {
            readBtn.disabled = false;
            readBtn.innerHTML = originalBtnHtml;
        }
    }
};
