const openDebtInstallmentsDetailsModal = (debtId) => {
    initDebtsDefaultsIfNeeded();
    const debt = (state.debts || []).find(d => String(d.id) === String(debtId));
    if (!debt) {
        showToast('لم يتم العثور على الدين المحدد.', 'error');
        return;
    }
    const modal = document.getElementById('modal-debt-installments-details');
    const titleEl = document.getElementById('dtl-debt-title');
    const subtitleEl = document.getElementById('dtl-debt-subtitle');
    const origAmtEl = document.getElementById('dtl-orig-amt');
    const paidAmtEl = document.getElementById('dtl-paid-amt');
    const remAmtEl = document.getElementById('dtl-rem-amt');
    const instAmtEl = document.getElementById('dtl-inst-amt');
    const tbody = document.getElementById('dtl-installments-tbody');
    if (titleEl)
        titleEl.textContent = `بيان أقساط: ${debt.debtTypeName}`;
    if (subtitleEl)
        subtitleEl.textContent = `المشترك: ${debt.customerName} | عداد: ${debt.meterNumber} (${debt.subscriptionCode})`;
    if (origAmtEl)
        origAmtEl.textContent = Number(debt.totalDebtAmount).toFixed(2) + ' ج.م';
    if (paidAmtEl)
        paidAmtEl.textContent = Number(debt.paidAmount).toFixed(2) + ' ج.م';
    if (remAmtEl)
        remAmtEl.textContent = Number(debt.remainingAmount).toFixed(2) + ' ج.م';
    if (instAmtEl)
        instAmtEl.textContent = Number(debt.installmentAmount).toFixed(2) + ' ج.م';
    if (tbody) {
        let installments = debt.installments || [];
        if (installments.length === 0) {
            // Generate sample installments if missing
            const count = debt.installmentsCount || 1;
            const instVal = debt.installmentAmount || (debt.totalDebtAmount / count);
            installments = [];
            for (let i = 1; i <= count; i++) {
                const isPaid = i <= (debt.paidInstallmentsCount || 0);
                installments.push({
                    seq: i,
                    dueDate: `2026-${String(i).padStart(2, '0')}-01`,
                    amount: Number(instVal.toFixed(2)),
                    paidAmount: isPaid ? Number(instVal.toFixed(2)) : 0,
                    status: isPaid ? 'مسدد' : (i === (debt.paidInstallmentsCount || 0) + 1 ? 'مستحق' : 'قادم'),
                    payDate: isPaid ? '2026-08-01' : null
                });
            }
            debt.installments = installments;
        }
        tbody.innerHTML = installments.map(inst => `
                <tr style="border-bottom: 1px solid #e2e8f0;">
                    <td style="padding: 8px 12px; font-weight: bold;">القسط ${inst.seq}</td>
                    <td style="padding: 8px 12px;">${inst.dueDate}</td>
                    <td style="padding: 8px 12px; font-family: monospace; font-weight: bold;">${Number(inst.amount).toFixed(2)} ج.م</td>
                    <td style="padding: 8px 12px; font-family: monospace; color: #16a34a;">${Number(inst.paidAmount).toFixed(2)} ج.م</td>
                    <td style="padding: 8px 12px;">${inst.payDate || '-'}</td>
                    <td style="padding: 8px 12px;">
                        <span style="padding: 2px 8px; border-radius: 10px; font-size: 0.8rem; font-weight: bold; ${inst.status === 'مسدد' ? 'background: #dcfce7; color: #166534;' : (inst.status === 'مستحق' ? 'background: #fee2e2; color: #991b1b;' : 'background: #f1f5f9; color: #475569;')}">${inst.status}</span>
                    </td>
                    <td style="padding: 8px 12px; text-align: center;">
                        ${inst.status !== 'مسدد' ? `
                            <button type="button" class="btn btn-sm btn-pay-single-inst" data-debt-id="${debt.id}" data-seq="${inst.seq}" style="background:#16a34a; color:#fff; border:none; padding:3px 8px; border-radius:4px; font-size:0.8rem; cursor:pointer; font-weight:bold;">سداد الآن</button>
                        ` : '<span style="color:#16a34a; font-size:0.85rem;">✓ مسدد</span>'}
                    </td>
                </tr>
            `).join('');
        // Bind single installment payment
        tbody.querySelectorAll('.btn-pay-single-inst').forEach(btn => {
            btn.addEventListener('click', async (e) => {
                const dId = e.currentTarget.getAttribute('data-debt-id');
                const seq = Number(e.currentTarget.getAttribute('data-seq'));
                if (dId && seq) {
                    await paySingleInstallment(dId, seq);
                    openDebtInstallmentsDetailsModal(dId);
                }
            });
        });
    }
    if (modal)
        modal.style.display = 'flex';
};
// Helper: Pay single installment
const paySingleInstallment = async (debtId, seq) => {
    const debt = (state.debts || []).find(d => String(d.id) === String(debtId));
    if (!debt)
        return;
    const inst = (debt.installments || []).find((i) => i.seq === seq);
    if (!inst || inst.status === 'مسدد')
        return;
    const payAmt = Number(inst.amount) || Number(debt.installmentAmount);
    inst.status = 'مسدد';
    inst.paidAmount = payAmt;
    inst.payDate = new Date().toLocaleDateString('ar-EG');
    debt.paidAmount = Number(((debt.paidAmount || 0) + payAmt).toFixed(2));
    debt.remainingAmount = Number(Math.max(0, (debt.remainingAmount || 0) - payAmt).toFixed(2));
    debt.paidInstallmentsCount = (debt.paidInstallmentsCount || 0) + 1;
    if (debt.remainingAmount <= 0) {
        debt.status = 'Completed';
        debt.statusName = 'منتهي ومسدد بالكامل';
    }
    await saveState();
    showToast(`تم سداد القسط ${seq} بنجاح بقيمة ${payAmt} ج.م`, 'success');
    logActivity('سداد قسط دين', `تم سداد القسط رقم ${seq} للمشترك ${debt.customerName} بقيمة ${payAmt} ج.م`);
    // Also sync with backend bridge if running
    fetch('http://127.0.0.1:5002/api/debts/pay-installment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ debtId, amount: payAmt, seq })
    }).catch(() => null);
};
// Helper: Delay debt
const delayCustomerDebt = async (debtId) => {
    const debt = (state.debts || []).find(d => String(d.id) === String(debtId));
    if (!debt)
        return;
    if (!confirm(`هل تريد تأجيل استحقاق دين ${debt.debtTypeName} للمشترك ${debt.customerName} لمدة 30 يوماً؟`))
        return;
    debt.status = 'Delayed';
    debt.statusName = 'مؤجل';
    const nextMonth = new Date(Date.now() + 30 * 86400000).toLocaleDateString('ar-EG');
    debt.nextDueDate = nextMonth;
    await saveState();
    showToast('تم تأجيل استحقاق الدين بنجاح', 'success');
    logActivity('تأجيل دين', `تم تأجيل موعد استحقاق دين ${debt.debtTypeName} للمشترك ${debt.customerName}`);
    renderDebtsManagementSection();
    fetch('http://127.0.0.1:5002/api/debts/delay', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ debtId, newDueDate: nextMonth })
    }).catch(() => null);
};
// Helper: Delete debt
const deleteCustomerDebt = async (debtId) => {
    const debt = (state.debts || []).find(d => String(d.id) === String(debtId));
    if (!debt)
        return;
    if (!confirm(`هل أنت متأكد من حذف دين "${debt.debtTypeName}" للمشترك "${debt.customerName}"؟`))
        return;
    await withAppLoading('جارٍ حذف سجل الدين وتحديث المنظومة...', async () => {
        state.debts = (state.debts || []).filter(d => String(d.id) !== String(debtId));
        await saveState();
        logActivity('حذف دين', `تم حذف دين ${debt.debtTypeName} للمشترك ${debt.customerName}`);
        renderDebtsManagementSection();
    }, 'تحديث تلقائي وفوري للسحابة وجميع الأجهزة ☁️', '🗑️');
    showToast('تم حذف الدين بنجاح', 'success');
};
// =========================================================================
// 1. قسم إدارة حسابات الديون والمديونيات (Debts Management Section - On-Demand Retrieval by Meter / Code)
// =========================================================================
let debtsManagementInitialized = false;
let currentSelectedDebtCustomer = null;
const renderDebtsManagementSection = () => {
    initDebtsDefaultsIfNeeded();
    if (!debtsManagementInitialized) {
        initDebtsManagementListeners();
        debtsManagementInitialized = true;
    }
    updateCustomerDebtsSummaryBox();
    renderDebtsTable();
};
// Helper: Find customer strictly by meter number or subscriber code (NO name search)
const findCustomerByMeterOrCode = (term) => {
    if (!term)
        return null;
    const cleanTerm = term.trim().toLowerCase();
    // 1. Check in state.meters
    for (const m of (state.meters || [])) {
        const mChassis = String(m.meterChassisNumber || '').trim().toLowerCase();
        const sCode = String(m.subscriptionCode || '').trim().toLowerCase();
        const mId = String(m.id || '').trim().toLowerCase();
        if (mChassis === cleanTerm || sCode === cleanTerm || mId === cleanTerm) {
            return {
                id: String(m.id || m.subscriptionCode),
                name: m.subscriberName || 'مشترك مسجل',
                code: m.subscriptionCode || '-',
                meterNumber: m.meterChassisNumber || '-'
            };
        }
    }
    // 2. Check in state.debts
    for (const d of (state.debts || [])) {
        const dMeter = String(d.meterNumber || '').trim().toLowerCase();
        const dCode = String(d.subscriptionCode || '').trim().toLowerCase();
        const dCustId = String(d.customerId || '').trim().toLowerCase();
        if (dMeter === cleanTerm || dCode === cleanTerm || dCustId === cleanTerm) {
            return {
                id: String(d.customerId || d.subscriptionCode),
                name: d.customerName || 'مشترك مسجل',
                code: d.subscriptionCode || '-',
                meterNumber: d.meterNumber || '-'
            };
        }
    }
    return null;
};
// Helper: Update Customer Debts Summary Form Panel
const updateCustomerDebtsSummaryBox = () => {
    const codeInput = document.getElementById('debts-summary-code');
    const nameInput = document.getElementById('debts-summary-name');
    const meterInput = document.getElementById('debts-summary-meter');
    const countInput = document.getElementById('debts-summary-count');
    const totalInput = document.getElementById('debts-summary-total-amount');
    const paidInput = document.getElementById('debts-summary-paid-amount');
    const remInput = document.getElementById('debts-summary-remaining-amount');
    if (!currentSelectedDebtCustomer) {
        if (codeInput)
            codeInput.value = '-';
        if (nameInput)
            nameInput.value = 'يرجى استدعاء مشترك برقم العداد أو الكود';
        if (meterInput)
            meterInput.value = '-';
        if (countInput)
            countInput.value = '0';
        if (totalInput)
            totalInput.value = '0.00 ج.م';
        if (paidInput)
            paidInput.value = '0.00 ج.م';
        if (remInput)
            remInput.value = '0.00 ج.م';
        return;
    }
    const cust = currentSelectedDebtCustomer;
    if (codeInput)
        codeInput.value = cust.code;
    if (nameInput)
        nameInput.value = cust.name;
    if (meterInput)
        meterInput.value = cust.meterNumber;
    // Filter debts strictly for this customer
    const custDebts = (state.debts || []).filter(d => (cust.meterNumber !== '-' && String(d.meterNumber || '').trim() === cust.meterNumber.trim()) ||
        (cust.code !== '-' && String(d.subscriptionCode || '').trim() === cust.code.trim()) ||
        String(d.customerId || '').trim() === cust.id.trim());
    const totalAmt = custDebts.reduce((s, d) => s + (Number(d.totalDebtAmount) || 0), 0);
    const paidAmt = custDebts.reduce((s, d) => s + (Number(d.paidAmount) || 0), 0);
    const remAmt = custDebts.reduce((s, d) => s + (Number(d.remainingAmount) || 0), 0);
    if (countInput)
        countInput.value = String(custDebts.length);
    if (totalInput)
        totalInput.value = totalAmt.toFixed(2) + ' ج.م';
    if (paidInput)
        paidInput.value = paidAmt.toFixed(2) + ' ج.م';
    if (remInput)
        remInput.value = remAmt.toFixed(2) + ' ج.م';
};
